mapper.insert:
INSERT INTO public.token_quotes ( token_id, unit, opening_price, high_price, low_price, closing_price, trade_volume, trade_amount, candle_time, created_at ) VALUES
( #{c.tokenId}, #{c.unit}, #{c.openingPrice}, #{c.highPrice}, #{c.lowPrice}, #{c.closingPrice}, #{c.tradeVolume}, #{c.tradeAmount}, #{c.candleTime}, NOW() )
ON CONFLICT (token_id, candle_time, unit) DO UPDATE SET opening_price = EXCLUDED.opening_price, high_price = EXCLUDED.high_price, low_price = EXCLUDED.low_price, closing_price = EXCLUDED.closing_price, trade_volume = EXCLUDED.trade_volume, trade_amount = EXCLUDED.trade_amount;
